const MUSTER = [
  [/(?:)\b(api[_-]?key|apikey|token|secret|password|passwort|pwd|authorization|bearer|credential|client[_-]?secret)\b\s*[:=]?\s*\S+/gi, "[entfernt]"],
  [/eyJ[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}/g, "[entfernt]"],
  [/(token|key|secret|password)=[^&\s]+/gi, "[entfernt]"],
  [/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, "[entfernt]"],
  [/postgres(?:ql)?:\/\/[^\s]+/gi, "[entfernt]"],
  [/\+?\d[\d\s()\/-]{7,}\d/g, "[entfernt]"]
];
const KONTEXTE = ["privat", "arbeitgeber_visolva"];
const ergebnis = [];

for (const item of $input.all()) {
  const kontext = item.json.context_id;
  if (KONTEXTE.indexOf(kontext) === -1) {
    throw new Error("tech_log_write_invalid_input: context_id nicht im Register");
  }
  if (!item.json.trace_id) {
    throw new Error("tech_log_write_invalid_input: trace_id fehlt");
  }
  if (!item.json.workflow_name) {
    throw new Error("tech_log_write_invalid_input: workflow_name fehlt");
  }

  let text = String(item.json.message_raw || "");
  for (const paar of MUSTER) {
    text = text.replace(paar[0], paar[1]);
  }
  if (text.length > 500) {
    text = text.slice(0, 497) + "...";
  }

  ergebnis.push({ json: {
    context_id: kontext,
    trace_id: item.json.trace_id,
    run_id: item.json.run_id || null,
    workflow_name: item.json.workflow_name,
    node_name: item.json.node_name || null,
    object_kind: item.json.object_kind || null,
    object_id: item.json.object_id || null,
    tool_id: item.json.tool_id || null,
    adapter_id: item.json.adapter_id || null,
    status_code: item.json.status_code === undefined ? null : item.json.status_code,
    error_class: item.json.error_class || null,
    message_safe: text,
    duration_ms: item.json.duration_ms === undefined ? null : item.json.duration_ms
  } });
}
return ergebnis;
